mapper.select:

WHERE c.OWNER_USERNAME = #{ownerUsername}
  AND c.USE_YN = 'Y'
ORDER BY c.SORT_ORDER, c.CATEGORY_NAME

SELECT EXISTS (
    SELECT 1 FROM TB_CATEGORY
    WHERE CATEGORY_NAME = #{categoryName}
      AND USE_YN = 'Y'
)

SELECT EXISTS (
    SELECT 1 FROM TB_CATEGORY
    WHERE CATEGORY_NAME = #{categoryName}
      AND CATEGORY_ID != #{categoryId}
      AND USE_YN = 'Y'
)

SELECT EXISTS (
    SELECT 1 FROM TB_CATEGORY
    WHERE CATEGORY_CODE = #{categoryCode}
      AND USE_YN = 'Y'
)

SELECT EXISTS (
    SELECT 1 FROM TB_CATEGORY
    WHERE CATEGORY_CODE = #{categoryCode}
      AND CATEGORY_ID != #{categoryId}
      AND USE_YN = 'Y'
)

SELECT COALESCE(MAX(SORT_ORDER), 0)
FROM TB_CATEGORY
WHERE OWNER_USERNAME = #{ownerUsername}

SELECT EXISTS (
    SELECT 1 FROM TB_BOARD_CATEGORY
    WHERE CATEGORY_ID = #{categoryId}
)
